const crypto = require('crypto');
const path = require('path');
const req = $input.first().json ?? {};
const payload = req.body ?? req;
const headers = Object.fromEntries(Object.entries(req.headers ?? {}).map(([key, value]) => [String(key).toLowerCase(), Array.isArray(value) ? String(value[0] ?? '') : String(value ?? '')]));
const secret = String($env.N8N_ASSET_WEBHOOK_SECRET || '').trim();
if (!secret) throw new Error('环境变量 N8N_ASSET_WEBHOOK_SECRET 未配置');
if (String(headers['x-openclaw-secret'] || '').trim() !== secret) throw new Error('Webhook 鉴权失败');
if (!payload || !Array.isArray(payload.assets) || payload.assets.length === 0) throw new Error('assets 必须是非空数组');

const safeId = /^[A-Za-z0-9_-]+$/;
const safeFilename = /^[A-Za-z0-9_-]+\.(?:png|jpg|jpeg|webp)$/i;
const shaPattern = /^sha256:[a-f0-9]{64}$/;
const allowedRatios = new Set(['1:1','2:3','3:2','3:4','4:3','4:5','5:4','9:16','16:9','21:9']);
const lockHeadings = [
  ['style_lock_text', '【STYLE LOCK｜固定原文】'],
  ['scene_or_subject_lock_text', '【SCENE DNA / SUBJECT DNA｜固定原文】'],
  ['spatial_or_structure_lock_text', '【SPATIAL LOCK / STRUCTURE LOCK｜固定原文】'],
  ['continuity_lock_text', '【CONTINUITY LOCK｜固定原文】'],
];
const stable = value => Array.isArray(value)
  ? value.map(stable)
  : value && typeof value === 'object'
    ? Object.fromEntries(Object.keys(value).sort().map(key => [key, stable(value[key])]))
    : value;
const sha = value => `sha256:${crypto.createHash('sha256').update(JSON.stringify(stable(value))).digest('hex')}`;
const payloadCopy = JSON.parse(JSON.stringify(payload));
delete payloadCopy.payload_sha256;
const computedPayloadSha = sha(payloadCopy);
if (!shaPattern.test(String(payload.payload_sha256 || '')) || payload.payload_sha256 !== computedPayloadSha) throw new Error('payload_sha256 缺失或不匹配');
if (String(headers['x-openclaw-payload-sha256'] || '') !== computedPayloadSha) throw new Error('请求头 Payload SHA256 不匹配');
if (!safeId.test(String(payload.project_id || '')) || !safeId.test(String(payload.job_id || ''))) throw new Error('project_id/job_id 只能包含 ASCII 字母、数字、下划线和连字符');
if ('shared_asset_root' in payload || 'shared_asset_root' in (payload.defaults || {})) throw new Error('shared_asset_root 禁止由 Payload 指定');

const extractLocks = prompt => {
  const text = String(prompt || '');
  const result = {};
  for (const [key, heading] of lockHeadings) {
    const startAt = text.indexOf(heading);
    if (startAt < 0) throw new Error(`缺少四锁标题：${heading}`);
    const contentStart = startAt + heading.length;
    let contentEnd = text.length;
    for (const [, nextHeading] of lockHeadings) {
      const candidate = text.indexOf(nextHeading, contentStart);
      if (candidate >= 0 && candidate < contentEnd) contentEnd = candidate;
    }
    const nextAny = text.slice(contentStart).match(/\n【[^】]+】/);
    if (nextAny) contentEnd = Math.min(contentEnd, contentStart + nextAny.index);
    const value = text.slice(contentStart, contentEnd).trim();
    if (!value) throw new Error(`四锁内容为空：${heading}`);
    result[key] = value;
  }
  return result;
};

const defaults = payload.defaults || {};
const root = path.resolve(String($env.OPENCLAW_ASSET_SHARED_ROOT || '/data/openclaw-assets'));
const ids = new Set();
const filenames = new Set();
const assetMap = new Map();
for (const raw of payload.assets) {
  if (!safeId.test(String(raw.asset_id || '')) || ids.has(raw.asset_id)) throw new Error(`asset_id 缺失、非法或重复：${raw.asset_id}`);
  if (!safeFilename.test(String(raw.filename || '')) || filenames.has(raw.filename)) throw new Error(`filename 缺失、非法或重复：${raw.filename}`);
  if (!String(raw.prompt_zh || '').startsWith('【PORTABLE HARD LOCK｜独立可用｜禁止删减】')) throw new Error(`${raw.asset_id} 缺少 PORTABLE HARD LOCK`);
  const computedLockHash = sha(extractLocks(raw.prompt_zh));
  if (!shaPattern.test(String(raw.lock_hash || '')) || raw.lock_hash !== computedLockHash) throw new Error(`${raw.asset_id} lock_hash 不匹配`);
  if (!raw.lock_id) throw new Error(`${raw.asset_id} 缺少 lock_id`);
  if (!allowedRatios.has(String(raw.aspect_ratio || ''))) throw new Error(`${raw.asset_id} 画幅不受支持`);
  if (['location','scene','shot'].includes(raw.category)) {
    if (!Array.isArray(raw.scene_ids) || raw.scene_ids.length === 0 || raw.scene_ids.some(id => !safeId.test(String(id)))) throw new Error(`${raw.asset_id} 缺少合法 scene_ids[]`);
    for (const key of ['location_id','sub_location_id','location_asset_id']) if (!safeId.test(String(raw[key] || ''))) throw new Error(`${raw.asset_id} 缺少 ${key}`);
  }
  if (raw.generation_stage === 'shot' && !safeId.test(String(raw.scene_id || ''))) throw new Error(`${raw.asset_id} shot 资产缺少 scene_id`);
  ids.add(raw.asset_id);
  filenames.add(raw.filename);
  assetMap.set(raw.asset_id, {
    ...raw,
    project_id: payload.project_id,
    job_id: payload.job_id,
    source: String(payload.source || 'openclaw'),
    payload_sha256: computedPayloadSha,
    model: String(raw.model || defaults.model || 'gemini-3.1-flash-image'),
    image_size: String(raw.image_size || defaults.image_size || '2K'),
    review_model: String(raw.review_model || defaults.review_model || 'gemini-2.5-flash'),
    review_min_score: Number(raw.review_min_score || defaults.review_min_score || 85),
    review_max_retries: Number(raw.review_max_retries ?? defaults.review_max_retries ?? 2),
    depends_on: Array.isArray(raw.depends_on) ? raw.depends_on : [],
    reference_inputs: Array.isArray(raw.reference_inputs) ? raw.reference_inputs : [],
    retry_count: 0,
    review_retry_count: 0,
    shared_asset_root: root,
  });
}
for (const asset of assetMap.values()) {
  const refs = new Set(asset.reference_inputs.map(ref => ref.asset_id));
  for (const ref of asset.reference_inputs) {
    if (!safeId.test(String(ref.asset_id || '')) || !String(ref.role || '').trim()) throw new Error(`${asset.asset_id} reference_inputs 非法`);
    if (ref.required && ref.approved_only !== true) throw new Error(`${asset.asset_id} 的必需参考必须 approved_only=true`);
  }
  for (const dep of asset.depends_on) {
    if (!safeId.test(String(dep || ''))) throw new Error(`${asset.asset_id} 依赖 ID 非法：${dep}`);
    if (!assetMap.has(dep) && !refs.has(dep)) throw new Error(`${asset.asset_id} 外部依赖未声明为 reference_input：${dep}`);
  }
}
const temporary = new Set();
const done = new Set();
const order = [];
function visit(id, stack = []) {
  if (done.has(id)) return;
  if (temporary.has(id)) throw new Error(`依赖图存在循环：${[...stack, id].join(' -> ')}`);
  temporary.add(id);
  const asset = assetMap.get(id);
  for (const dep of asset.depends_on) if (assetMap.has(dep)) visit(dep, [...stack, id]);
  temporary.delete(id);
  done.add(id);
  order.push(asset);
}
for (const id of assetMap.keys()) visit(id);
return order.map(asset => ({ json: asset }));

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const asset = $json;
const root = path.resolve(String($env.OPENCLAW_ASSET_SHARED_ROOT || '/data/openclaw-assets'));
const projectDir = path.resolve(root, asset.project_id);
if (projectDir !== root && !projectDir.startsWith(`${root}${path.sep}`)) throw new Error('projectDir 越出共享资产根目录');
const jobDir = path.resolve(projectDir, asset.job_id);
if (!jobDir.startsWith(`${projectDir}${path.sep}`)) throw new Error('jobDir 越出项目目录');
const registryPath = path.join(projectDir, 'reference_registry.json');
const outputPath = path.resolve(jobDir, asset.filename);
if (!outputPath.startsWith(`${jobDir}${path.sep}`)) throw new Error('output_path 越出 Job 目录');
fs.mkdirSync(jobDir, { recursive: true });
let registry = { schema_version: '2.1', project_id: asset.project_id, updated_at: new Date().toISOString(), assets: {} };
if (fs.existsSync(registryPath)) registry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
if (registry.project_id && registry.project_id !== asset.project_id) throw new Error('reference_registry project_id 不匹配');
const fileSha = target => `sha256:${crypto.createHash('sha256').update(fs.readFileSync(target)).digest('hex')}`;
const parts = [];
const refsUsed = [];
for (const ref of (asset.reference_inputs || [])) {
  const entry = registry.assets?.[ref.asset_id];
  if (!entry || entry.status !== 'approved') {
    if (ref.required) throw new Error(`${asset.asset_id} 缺少已通过参考图：${ref.asset_id}`);
    continue;
  }
  const referencePath = path.resolve(String(entry.path || ''));
  if (!referencePath.startsWith(`${projectDir}${path.sep}`) || !fs.isFileSync(referencePath)) {
    if (ref.required) throw new Error(`${asset.asset_id} 参考图路径非法或不存在：${ref.asset_id}`);
    continue;
  }
  const actualSize = fs.statSync(referencePath).size;
  const actualSha = fileSha(referencePath);
  if (entry.file_size !== actualSize || entry.sha256 !== actualSha) throw new Error(`${asset.asset_id} 参考图完整性失败：${ref.asset_id}`);
  const mime = entry.mime_type || (/\.jpe?g$/i.test(referencePath) ? 'image/jpeg' : 'image/png');
  parts.push({ text: `[REFERENCE ${refsUsed.length + 1}] asset_id=${ref.asset_id}; role=${ref.role}. 只按该职责使用，不复制其摄影机角度。` });
  parts.push({ inline_data: { mime_type: mime, data: fs.readFileSync(referencePath).toString('base64') } });
  refsUsed.push({ asset_id: ref.asset_id, role: ref.role, path: referencePath, sha256: actualSha });
}
let prompt = String(asset.prompt_zh || asset.prompt_en || '').trim();
if (asset.negative_prompt) prompt += `\n\n【补充负面约束】\n${asset.negative_prompt}`;
if (asset.qa_feedback) prompt += `\n\n【上轮质检修复要求】\n${asset.qa_feedback}`;
parts.push({ text: prompt });
const requestBody = {
  contents: [{ role: 'user', parts }],
  generationConfig: { responseModalities: ['TEXT', 'IMAGE'], responseFormat: { image: { aspectRatio: asset.aspect_ratio, imageSize: asset.image_size } } },
};
return [{ json: { ...asset, project_dir: projectDir, job_dir: jobDir, registry_path: registryPath, output_path: outputPath, refs_used: refsUsed, requestBody } }];

const meta = $('解析依赖并构建Gemini请求').item.json;
const parts = $json.candidates?.[0]?.content?.parts ?? [];
const imagePart = parts.find(p => (p.inlineData || p.inline_data) && !p.thought);
const inline = imagePart?.inlineData || imagePart?.inline_data;
const base64 = inline?.data || null;
const mime = inline?.mimeType || inline?.mime_type || 'image/png';
return [{ json: { ...meta, success: Boolean(base64), base64, mime_type: mime, provider_text: parts.filter(p=>p.text).map(p=>p.text).join('\n') || null } }];

const a = $json;
const prompt = [
  '你是严格的连续视觉资产质检员。只输出JSON。',
  `资产ID：${a.asset_id}`,
  `资产名称：${a.name}`,
  `原始Prompt：${a.prompt_zh}`,
  `参考图职责：${JSON.stringify(a.refs_used || [])}`,
  '检查：主体身份、关键结构、空间关系、画幅、风格、硬锁和参考一致性。',
  '返回格式：{"score":0-100,"passed":true或false,"reason":"...","problems":["..."],"hard_failures":["..."]}'
].join('\n');
return [{ json: { ...a, review_request_body: { contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: a.mime_type, data: a.base64 } }] }], generationConfig: { responseMimeType: 'application/json' } } } }];

const meta = $('准备图片质检请求').item.json;
const text = ($json.candidates?.[0]?.content?.parts ?? []).filter(p=>p.text).map(p=>p.text).join('\n').trim();
let data;
try { data = JSON.parse(text.replace(/^```json\s*|\s*```$/g,'')); }
catch { data = {score:0,passed:false,reason:'质检响应无法解析',problems:[text],hard_failures:['invalid_review_json']}; }
const score = Number(data.score || 0);
const passed = Boolean(data.passed) && score >= Number(meta.review_min_score || 85) && !(data.hard_failures || []).length;
return [{ json: { ...meta, review_score: score, review_passed: passed, review_reason: String(data.reason || ''), review_problems: data.problems || [], review_hard_failures: data.hard_failures || [] } }];

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const meta = $('提取生成图片').item.json;
if (!meta.base64) throw new Error('缺少生成图片 Base64');
const bytes = Buffer.from(meta.base64, 'base64');
if (!bytes.length) throw new Error('生成图片为空');
fs.mkdirSync(path.dirname(meta.output_path), { recursive: true });
fs.writeFileSync(meta.output_path, bytes);
const sha256 = `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`;
const lockDir = `${meta.registry_path}.lock`;
try {
  fs.mkdirSync(lockDir);
} catch (error) {
  throw new Error(`REGISTRY_WRITE_LOCKED: ${error.message}`);
}
try {
  let registry = { schema_version: '2.1', project_id: meta.project_id, updated_at: new Date().toISOString(), assets: {} };
  if (fs.existsSync(meta.registry_path)) registry = JSON.parse(fs.readFileSync(meta.registry_path, 'utf8'));
  registry.schema_version = '2.1';
  registry.project_id = meta.project_id;
  registry.assets = registry.assets || {};
  registry.updated_at = new Date().toISOString();
  registry.assets[meta.asset_id] = {
    asset_id: meta.asset_id,
    parent_asset_id: meta.parent_asset_id || null,
    filename: meta.filename,
    path: meta.output_path,
    mime_type: meta.mime_type || 'image/png',
    status: 'approved',
    qa_score: Number(meta.review_score || 100),
    anchor_roles: meta.anchor_roles || [],
    lock_id: meta.lock_id,
    lock_hash: meta.lock_hash,
    job_id: meta.job_id,
    payload_sha256: meta.payload_sha256,
    sha256,
    file_size: bytes.length,
    generated_at: new Date().toISOString(),
  };
  const temp = `${meta.registry_path}.tmp-${process.pid}-${Date.now()}-${crypto.randomUUID()}`;
  fs.writeFileSync(temp, JSON.stringify(registry, null, 2), 'utf8');
  fs.renameSync(temp, meta.registry_path);
} finally {
  fs.rmSync(lockDir, { recursive: true, force: true });
}
return [{ json: { ...meta, final_status: 'approved', registry_path: meta.registry_path, sha256, file_size: bytes.length } }];

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const asset = $json;
const projectDir = path.resolve(asset.shared_asset_root, asset.project_id);
const jobDir = path.resolve(projectDir, asset.job_id);
const rejectedDir = path.join(jobDir, '_rejected');
fs.mkdirSync(rejectedDir, { recursive: true });
const rejectedPath = path.join(rejectedDir, String(asset.filename).replace(/\.[^.]+$/, '') + `_REJECTED_score_${asset.review_score}.png`);
const bytes = asset.base64 ? Buffer.from(asset.base64, 'base64') : Buffer.alloc(0);
if (bytes.length) fs.writeFileSync(rejectedPath, bytes);
const registryPath = path.join(projectDir, 'reference_registry.json');
const lockDir = `${registryPath}.lock`;
try { fs.mkdirSync(lockDir); } catch (error) { throw new Error(`REGISTRY_WRITE_LOCKED: ${error.message}`); }
try {
  let registry = { schema_version: '2.1', project_id: asset.project_id, updated_at: new Date().toISOString(), assets: {} };
  if (fs.existsSync(registryPath)) registry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
  registry.schema_version = '2.1'; registry.project_id = asset.project_id; registry.assets = registry.assets || {}; registry.updated_at = new Date().toISOString();
  registry.assets[asset.asset_id] = {
    asset_id: asset.asset_id, filename: asset.filename, path: bytes.length ? rejectedPath : '', status: 'rejected',
    qa_score: asset.review_score, reason: asset.review_reason, lock_id: asset.lock_id, lock_hash: asset.lock_hash,
    job_id: asset.job_id, payload_sha256: asset.payload_sha256,
    sha256: `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`, file_size: bytes.length,
    generated_at: new Date().toISOString(),
  };
  const temp = `${registryPath}.tmp-${process.pid}-${Date.now()}-${crypto.randomUUID()}`;
  fs.writeFileSync(temp, JSON.stringify(registry, null, 2), 'utf8'); fs.renameSync(temp, registryPath);
} finally { fs.rmSync(lockDir, { recursive: true, force: true }); }
return [{ json: { ...asset, final_status: 'rejected', rejected_path: bytes.length ? rejectedPath : '' } }];

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const asset = $json;
const projectDir = path.resolve(asset.shared_asset_root, asset.project_id);
const registryPath = path.join(projectDir, 'reference_registry.json');
fs.mkdirSync(projectDir, { recursive: true });
const lockDir = `${registryPath}.lock`;
try { fs.mkdirSync(lockDir); } catch (error) { throw new Error(`REGISTRY_WRITE_LOCKED: ${error.message}`); }
try {
  let registry = { schema_version: '2.1', project_id: asset.project_id, updated_at: new Date().toISOString(), assets: {} };
  if (fs.existsSync(registryPath)) registry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
  registry.schema_version = '2.1'; registry.project_id = asset.project_id; registry.assets = registry.assets || {}; registry.updated_at = new Date().toISOString();
  registry.assets[asset.asset_id] = {
    asset_id: asset.asset_id, filename: asset.filename, path: '', status: 'failed', reason: 'empty_image',
    lock_id: asset.lock_id, lock_hash: asset.lock_hash, job_id: asset.job_id, payload_sha256: asset.payload_sha256,
    sha256: `sha256:${crypto.createHash('sha256').update(Buffer.alloc(0)).digest('hex')}`, file_size: 0,
    generated_at: new Date().toISOString(),
  };
  const temp = `${registryPath}.tmp-${process.pid}-${Date.now()}-${crypto.randomUUID()}`;
  fs.writeFileSync(temp, JSON.stringify(registry, null, 2), 'utf8'); fs.renameSync(temp, registryPath);
} finally { fs.rmSync(lockDir, { recursive: true, force: true }); }
return [{ json: { ...asset, final_status: 'failed_empty_image' } }];

const fs = require('fs');
const path = require('path');
const first = $('校验任务并拓扑排序').first().json;
const registryPath = path.join(first.shared_asset_root, first.project_id, 'reference_registry.json');
let registry = { assets: {} };
if (fs.existsSync(registryPath)) registry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
const requested = $items('校验任务并拓扑排序').map(item => item.json);
const assets = requested.map(asset => {
  const entry = registry.assets?.[asset.asset_id];
  const binding_valid = Boolean(entry && entry.job_id === first.job_id && entry.payload_sha256 === first.payload_sha256 && entry.lock_hash === asset.lock_hash);
  return { asset_id: asset.asset_id, status: binding_valid ? entry.status : 'unknown', binding_valid };
});
const approved_count = assets.filter(asset => asset.status === 'approved' && asset.binding_valid).length;
const failed_count = assets.length - approved_count;
const ok = assets.length > 0 && failed_count === 0;
return [{ json: {
  ok,
  project_id: first.project_id,
  job_id: first.job_id,
  payload_sha256: first.payload_sha256,
  registry_path: registryPath,
  approved_count,
  failed_count,
  all_required_assets_approved: ok,
  assets,
} }];
